document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("weight-form"),t=document.getElementById("weight-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("weight-m").value);if(n<0)return t.textContent="Mass cannot be negative.",void 0;const o=9.81*n;t.innerHTML=`<b>Gravitational Force:</b> ${o.toFixed(3)} N`})});